    private static Unit unit(String id) {
        for (Unit u : UNITS) {
            if (u.id.equals(id)) {
                return u;
            }
        }
        throw new IllegalStateException("unknown unit: " + id);
    }

    private static void addTo(String unitId, Item item) {
        unit(unitId).items.add(item);
    }

    /** The item just added to a unit, so a legacy list can share it. */
    private static Item lastOf(String unitId) {
        List<Item> items = unit(unitId).items;
        return items.get(items.size() - 1);
    }

    private static void add(List<Item> list, Item item) {
        list.add(item);
    }

    private static void addSentenceTo(String unitId, String en, String ms) {
        unit(unitId).sentences.add(new Sentence(en, ms));
    }

    private static void addSentence(String en, String ms) {
        SENTENCES.add(new Sentence(en, ms));
        SENTENCES_EN.add(new Sentence(en, ms));
    }

    public static Unit unitById(String id) {
        for (Unit u : UNITS) {
            if (u.id.equals(id)) {
                return u;
            }
        }
        return null;
    }

    public static Tunjang tunjangById(String id) {
        for (Tunjang t : TUNJANG) {
            if (t.id.equals(id)) {
                return t;
            }
        }
        return null;
    }

    /** Letter items store their symbol as "A|emoji" so glyph and picture travel together. */
    public static String letterGlyph(Item item) {
        int bar = item.symbol.indexOf('|');
        return bar < 0 ? item.symbol : item.symbol.substring(0, bar);
    }

    public static String letterEmoji(Item item) {
        int bar = item.symbol.indexOf('|');
        return bar < 0 ? "\u2B50" : item.symbol.substring(bar + 1);
    }

    /**
     * True when the item is one letter of the alphabet.
     *
     * Decided from the symbol shape ("A|emoji") rather than by looking the item
     * up in a list, so an item taken out of a unit behaves the same as one taken
     * out of LETTERS.
     */
    public static boolean isLetterItem(Item item) {
        if (item == null || item.symbol == null || item.symbol.indexOf('|') <= 0) {
            return false;
        }
        String glyph = letterGlyph(item);
        return glyph.length() == 1 && Character.isLetter(glyph.charAt(0));
    }

    /**
     * The character to draw when an item is shown as a single big symbol.
     *
     * A letter's symbol is stored as "A|emoji" so drawing the raw symbol would
     * print the pipe and the picture next to the letter. Anything that shows one
     * character must go through here instead.
     */
    public static String glyphOf(Item item) {
        if (item == null) {
            return "";
        }
        return isLetterItem(item) ? letterGlyph(item) : item.symbol;
    }

    /** Colour items are stored as "#RRGGBB" so flashcards and the quiz can render them. */
    public static boolean isColorItem(Item item) {
        return item != null && item.symbol != null && item.symbol.length() == 7
                && item.symbol.charAt(0) == '#';
    }

    public static int colorOf(Item item) {
        try {
            return (int) Long.parseLong(item.symbol.substring(1), 16) | 0xFF000000;
        } catch (NumberFormatException e) {
            return 0xFF000000;
        }
    }

    /** Jawi/Arabic items are shown with the script glyph big and no picture. */
    public static boolean isScriptItem(Item item) {
        if (item == null || item.symbol == null || item.symbol.isEmpty()) {
            return false;
        }
        char c = item.symbol.charAt(0);
        return c >= 0x0600 && c <= 0x06FF;
    }

    /**
     * What to draw on a tile for this item.
     *
     * A letter shows only the letter, never the "A|emoji" storage form, and a
     * colour shows a swatch marker rather than a hex string.
     */
    public static String displayOf(Item item, Lang lang) {
        if (item == null) {
            return "";
        }
        if (isColorItem(item)) {
            return "\u25CF";
        }
        return glyphOf(item);
    }

    /**
     * What to say for this item.
     *
     * A letter must be read as its name ("ei"), never as the picture beside it,
     * which is the whole point of the ABC unit. Everything else uses the item's
     * own spoken text, which already handles numbers and reading words.
     */
    public static String spokenOf(Item item, String kind, Lang lang) {
        if (item == null) {
            return "";
        }
        if ("letter".equals(kind)) {
            String explicit = lang == Lang.MS ? item.spokenMs : item.spokenEn;
            if (explicit != null && !explicit.isEmpty()) {
                return explicit;
            }
            return letterGlyph(item);
        }
        return item.spokenText(lang);
    }

    /** The tunjang a unit belongs to, or null when the id is unknown. */
    public static String tunjangIdOf(Unit unit) {
        if (unit == null) {
            return null;
        }
        for (Tunjang t : TUNJANG) {
            if (t.units.contains(unit)) {
                return t.id;
            }
        }
        return null;
    }

